SELECT p.sku, p.path, p.brand, p.series, p.model, p.category_id, json_extract(p.properties,'$.adhesive_type') AS adhesive_type FROM products p WHERE p.brand='Gorilla' AND p.series LIKE '%Gorilla Crystal Grip%' AND p.model='2ZQ-D83' AND p.category_id='adhesives_and_glues' AND json_extract(p.properties,'$.adhesive_type')='epoxy' LIMIT 10;

SELECT s.store_id, s.name, s.city FROM stores s WHERE s.city='Vienna' ORDER BY s.store_id;

SELECT s.store_id, s.name, i.sku, i.available_today FROM inventory i JOIN stores s ON s.store_id=i.store_id WHERE s.city='Vienna' AND i.sku IN (SELECT p.sku FROM products p WHERE p.brand='Gorilla' AND p.series LIKE '%Gorilla Crystal Grip%' AND p.model='2ZQ-D83' AND p.category_id='adhesives_and_glues' AND json_extract(p.properties,'$.adhesive_type')='epoxy') ORDER BY s.store_id;

